 30	export default async function ProductPage({
 31	  params,
 32	}: {
 33	  params: Promise<{ slug: string }>
 34	}) {
 35	  const { slug } = await params
 36	  const product = products.find((p) => p.slug === slug)
 37	  if (!product) notFound()
 38	
 39	  return (
 40	    <ViewTransition
 41	      enter={{
 42	        'nav-forward': 'nav-forward',
 43	        'nav-back': 'nav-back',
 44	        default: 'none',
 45	      }}
 46	      exit={{
 47	        'nav-forward': 'nav-forward',
 48	        'nav-back': 'nav-back',
 49	        default: 'none',
 50	      }}
 51	      default="none"
 52	    >
 53	      <main>
 54	        <Link
 55	          href="/"
 56	          className="back-link"
 57	          transitionTypes={['nav-back']}
 58	        >
 59	          ← Back to products
 60	        </Link>
 61	        <div className="product-detail">
 62	          <ViewTransition
 63	            name={`product-${product.slug}`}
 64	            share="product-image-morph"
 65	            default="none"
 66	          >
 67	            <div
 68	              className="product-hero"
 69	              style={{ backgroundColor: product.color }}
 70	            />
 71	          </ViewTransition>
 72	          <Suspense
 73	            fallback={
 74	              <ViewTransition exit="skeleton-exit">
 75	                <DetailsSkeleton />
 76	              </ViewTransition>
 77	            }
 78	          >
 79	            <ViewTransition enter="content-enter" default="none">
 80	              <ProductDetails slug={slug} />
 81	            </ViewTransition>
 82	          </Suspense>
 83	        </div>
 84	      </main>
 85	    </ViewTransition>
 86	  )
 87	}
